/* Rehab ZSC — Login (estilo hospitalario: calma, confianza, seguridad) */

:root {
  --color-primary: #0d7377;
  --color-primary-dark: #095456;
  --color-primary-light: #14a098;
  --color-accent: #3282b8;
  --color-bg: #f0f7fa;
  --color-surface: #ffffff;
  --color-text: #1a365d;
  --color-text-muted: #5a7184;
  --color-border: #d1e3ec;
  --color-error: #c53030;
  --color-error-bg: #fff5f5;
  --color-success: #276749;
  --color-success-bg: #f0fff4;
  --shadow-sm: 0 1px 3px rgba(26, 54, 93, 0.08);
  --shadow-md: 0 4px 20px rgba(26, 54, 93, 0.12);
  --shadow-lg: 0 8px 40px rgba(26, 54, 93, 0.15);
  --radius: 12px;
  --radius-sm: 8px;
  --transition: 0.2s ease;
  --font: 'Inter', system-ui, -apple-system, sans-serif;
}

*,
*::before,
*::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

html {
  font-size: 16px;
  -webkit-font-smoothing: antialiased;
}

body {
  font-family: var(--font);
  background: var(--color-bg);
  color: var(--color-text);
  min-height: 100vh;
  line-height: 1.5;
}

/* Layout principal */
.login-page {
  display: grid;
  grid-template-columns: 1fr 1fr;
  min-height: 100vh;
}

/* Panel visual izquierdo */
.login-visual {
  position: relative;
  overflow: hidden;
  display: flex;
  align-items: flex-end;
}

.visual-image {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.visual-overlay {
  position: absolute;
  inset: 0;
  background: linear-gradient(
    160deg,
    rgba(13, 115, 119, 0.75) 0%,
    rgba(26, 54, 93, 0.85) 60%,
    rgba(9, 84, 86, 0.95) 100%
  );
  z-index: 1;
}

.visual-content {
  position: relative;
  z-index: 2;
  padding: 3rem;
  color: #fff;
  width: 100%;
}

.visual-badge {
  display: inline-flex;
  align-items: center;
  gap: 0.5rem;
  background: rgba(255, 255, 255, 0.15);
  backdrop-filter: blur(8px);
  border: 1px solid rgba(255, 255, 255, 0.25);
  border-radius: 2rem;
  padding: 0.5rem 1rem;
  font-size: 0.8125rem;
  font-weight: 500;
  letter-spacing: 0.02em;
  margin-bottom: 2rem;
}

.visual-badge svg {
  width: 16px;
  height: 16px;
}

.visual-quote {
  border: none;
  margin-bottom: 1.5rem;
}

.visual-quote p {
  font-size: 1.75rem;
  font-weight: 300;
  line-height: 1.4;
  letter-spacing: -0.01em;
  max-width: 28rem;
}

.visual-credit {
  font-size: 0.75rem;
  opacity: 0.6;
}

.visual-credit a {
  color: inherit;
}

/* Panel de login derecho */
.login-panel {
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 2rem;
  background: var(--color-bg);
  background-image:
    radial-gradient(ellipse at 80% 20%, rgba(50, 130, 184, 0.06) 0%, transparent 50%),
    radial-gradient(ellipse at 20% 80%, rgba(13, 115, 119, 0.06) 0%, transparent 50%);
}

.login-container {
  width: 100%;
  max-width: 420px;
}

/* Cabecera */
.login-header {
  text-align: center;
  margin-bottom: 2.5rem;
}

.brand-logo {
  display: inline-flex;
  color: var(--color-primary);
  margin-bottom: 1rem;
}

.brand-logo svg {
  width: 56px;
  height: 56px;
}

.login-header h1 {
  font-size: 1.75rem;
  font-weight: 700;
  color: var(--color-text);
  letter-spacing: -0.02em;
}

.login-subtitle {
  margin-top: 0.375rem;
  font-size: 0.9375rem;
  color: var(--color-text-muted);
  font-weight: 400;
}

/* Formulario */
.login-form {
  background: var(--color-surface);
  border-radius: var(--radius);
  padding: 2rem;
  box-shadow: var(--shadow-md);
  border: 1px solid var(--color-border);
}

.form-group {
  margin-bottom: 1.25rem;
}

.form-group label {
  display: block;
  font-size: 0.8125rem;
  font-weight: 600;
  color: var(--color-text);
  margin-bottom: 0.5rem;
  letter-spacing: 0.01em;
}

.input-wrapper {
  position: relative;
  display: flex;
  align-items: center;
}

.input-icon {
  position: absolute;
  left: 0.875rem;
  width: 18px;
  height: 18px;
  color: var(--color-text-muted);
  pointer-events: none;
  transition: color var(--transition);
}

.input-wrapper input {
  width: 100%;
  padding: 0.75rem 2.75rem 0.75rem 2.75rem;
  font-family: var(--font);
  font-size: 0.9375rem;
  color: var(--color-text);
  background: var(--color-bg);
  border: 1.5px solid var(--color-border);
  border-radius: var(--radius-sm);
  outline: none;
  transition: border-color var(--transition), box-shadow var(--transition), background var(--transition);
}

.input-wrapper input::placeholder {
  color: #a0aec0;
}

.input-wrapper input:focus {
  background: var(--color-surface);
  border-color: var(--color-primary);
  box-shadow: 0 0 0 3px rgba(13, 115, 119, 0.15);
}

.input-wrapper input:focus + .input-icon,
.input-wrapper:focus-within .input-icon {
  color: var(--color-primary);
}

.input-wrapper input.error {
  border-color: var(--color-error);
  background: var(--color-error-bg);
}

.toggle-password {
  position: absolute;
  right: 0.625rem;
  background: none;
  border: none;
  cursor: pointer;
  padding: 0.25rem;
  color: var(--color-text-muted);
  display: flex;
  align-items: center;
  transition: color var(--transition);
}

.toggle-password:hover {
  color: var(--color-primary);
}

.toggle-password svg {
  width: 18px;
  height: 18px;
}

.field-error {
  display: block;
  font-size: 0.75rem;
  color: var(--color-error);
  margin-top: 0.375rem;
  min-height: 1rem;
}

/* Alertas */
.alert {
  padding: 0.75rem 1rem;
  border-radius: var(--radius-sm);
  font-size: 0.875rem;
  margin-bottom: 1.25rem;
  display: flex;
  align-items: center;
  gap: 0.5rem;
}

.alert.error {
  background: var(--color-error-bg);
  color: var(--color-error);
  border: 1px solid #fed7d7;
}

.alert.success {
  background: var(--color-success-bg);
  color: var(--color-success);
  border: 1px solid #c6f6d5;
}

/* Botón principal */
.btn-primary {
  width: 100%;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 0.5rem;
  padding: 0.875rem 1.5rem;
  margin-top: 0.5rem;
  font-family: var(--font);
  font-size: 1rem;
  font-weight: 600;
  color: #fff;
  background: linear-gradient(135deg, var(--color-primary) 0%, var(--color-primary-light) 100%);
  border: none;
  border-radius: var(--radius-sm);
  cursor: pointer;
  box-shadow: 0 2px 8px rgba(13, 115, 119, 0.35);
  transition: transform var(--transition), box-shadow var(--transition), opacity var(--transition);
}

.btn-primary:hover:not(:disabled) {
  transform: translateY(-1px);
  box-shadow: 0 4px 16px rgba(13, 115, 119, 0.45);
}

.btn-primary:active:not(:disabled) {
  transform: translateY(0);
}

.btn-primary:disabled {
  opacity: 0.7;
  cursor: not-allowed;
}

.btn-spinner svg {
  width: 20px;
  height: 20px;
  animation: spin 0.8s linear infinite;
}

@keyframes spin {
  to { transform: rotate(360deg); }
}

/* Footer */
.login-footer {
  margin-top: 2rem;
  text-align: center;
}

.security-note {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 0.5rem;
  font-size: 0.75rem;
  color: var(--color-text-muted);
  margin-bottom: 0.75rem;
}

.security-note svg {
  width: 14px;
  height: 14px;
  flex-shrink: 0;
  color: var(--color-primary);
}

.copyright {
  font-size: 0.75rem;
  color: #a0aec0;
}

/* Responsive */
@media (max-width: 900px) {
  .login-page {
    grid-template-columns: 1fr;
    grid-template-rows: auto 1fr;
  }

  .login-visual {
    min-height: 220px;
  }

  .visual-quote p {
    font-size: 1.25rem;
  }

  .visual-content {
    padding: 1.5rem;
  }

  .visual-credit {
    display: none;
  }
}

@media (max-width: 480px) {
  .login-panel {
    padding: 1rem;
  }

  .login-form {
    padding: 1.5rem;
  }
}

/**
 * Rehab ZSC — Lógica de login
 * Envía credenciales al servidor para verificación en base de datos.
 */

(function () {
  'use strict';

  const form = document.getElementById('loginForm');
  const usernameInput = document.getElementById('username');
  const passwordInput = document.getElementById('password');
  const usernameError = document.getElementById('usernameError');
  const passwordError = document.getElementById('passwordError');
  const alertBox = document.getElementById('alertBox');
  const submitBtn = document.getElementById('submitBtn');
  const btnText = submitBtn.querySelector('.btn-text');
  const btnSpinner = submitBtn.querySelector('.btn-spinner');
  const togglePassword = document.getElementById('togglePassword');

  const API_URL = '/api/auth/login';

  /* Mostrar / ocultar contraseña */
  togglePassword.addEventListener('click', () => {
    const isPassword = passwordInput.type === 'password';
    passwordInput.type = isPassword ? 'text' : 'password';
    togglePassword.querySelector('.icon-show').hidden = isPassword;
    togglePassword.querySelector('.icon-hide').hidden = !isPassword;
    togglePassword.setAttribute('aria-label', isPassword ? 'Ocultar contraseña' : 'Mostrar contraseña');
  });

  function showAlert(message, type) {
    alertBox.textContent = message;
    alertBox.className = `alert ${type}`;
    alertBox.hidden = false;
  }

  function hideAlert() {
    alertBox.hidden = true;
    alertBox.textContent = '';
  }

  function clearFieldErrors() {
    usernameError.textContent = '';
    passwordError.textContent = '';
    usernameInput.classList.remove('error');
    passwordInput.classList.remove('error');
  }

  function setFieldError(input, errorEl, message) {
    input.classList.add('error');
    errorEl.textContent = message;
  }

  function validateForm() {
    clearFieldErrors();
    hideAlert();
    let valid = true;

    const username = usernameInput.value.trim();
    const password = passwordInput.value;

    if (!username) {
      setFieldError(usernameInput, usernameError, 'El usuario es obligatorio.');
      valid = false;
    } else if (username.length < 3) {
      setFieldError(usernameInput, usernameError, 'El usuario debe tener al menos 3 caracteres.');
      valid = false;
    }

    if (!password) {
      setFieldError(passwordInput, passwordError, 'La contraseña es obligatoria.');
      valid = false;
    } else if (password.length < 4) {
      setFieldError(passwordInput, passwordError, 'La contraseña debe tener al menos 4 caracteres.');
      valid = false;
    }

    return valid;
  }

  function setLoading(loading) {
    submitBtn.disabled = loading;
    btnText.hidden = loading;
    btnSpinner.hidden = !loading;
  }

  async function handleSubmit(event) {
    event.preventDefault();

    if (!validateForm()) return;

    const credentials = {
      username: usernameInput.value.trim(),
      password: passwordInput.value,
    };

    setLoading(true);
    hideAlert();

    try {
      const response = await fetch(API_URL, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(credentials),
      });

      const data = await response.json();

      if (response.ok && data.success) {
        showAlert('Acceso concedido. Redirigiendo…', 'success');
        sessionStorage.setItem('rehabZsc_user', JSON.stringify(data.user));
        setTimeout(() => {
          window.location.href = 'dashboard.html';
        }, 800);
      } else {
        showAlert(data.message || 'Usuario o contraseña incorrectos.', 'error');
        passwordInput.value = '';
        passwordInput.focus();
      }
    } catch {
      showAlert('No se pudo conectar con el servidor. Inténtelo de nuevo.', 'error');
    } finally {
      setLoading(false);
    }
  }

  form.addEventListener('submit', handleSubmit);

  [usernameInput, passwordInput].forEach((input) => {
    input.addEventListener('input', () => {
      input.classList.remove('error');
      if (input === usernameInput) usernameError.textContent = '';
      if (input === passwordInput) passwordError.textContent = '';
    });
  });
})();

const Database = require('better-sqlite3');
const bcrypt = require('bcryptjs');
const path = require('path');
const fs = require('fs');

const DB_PATH = process.env.DB_PATH || path.join(__dirname, '..', 'data', 'rehabzsc.db');
const SALT_ROUNDS = 10;

function ensureDataDir() {
  const dir = path.dirname(DB_PATH);
  if (!fs.existsSync(dir)) {
    fs.mkdirSync(dir, { recursive: true });
  }
}

function initDatabase() {
  ensureDataDir();

  const db = new Database(DB_PATH);
  db.pragma('journal_mode = WAL');
  db.pragma('foreign_keys = ON');

  const schema = fs.readFileSync(path.join(__dirname, 'schema.sql'), 'utf8');
  db.exec(schema);

  seedDefaultUser(db);

  return db;
}

function seedDefaultUser(db) {
  const count = db.prepare('SELECT COUNT(*) AS total FROM usuarios').get().total;

  if (count === 0) {
    const hash = bcrypt.hashSync('Rehab2026!', SALT_ROUNDS);
    db.prepare(`
      INSERT INTO usuarios (username, password, nombre, rol)
      VALUES (?, ?, ?, ?)
    `).run('admin', hash, 'Administrador Rehab ZSC', 'administrador');

    console.log('Usuario demo creado → usuario: admin | contraseña: Rehab2026!');
  }
}

function findUserByUsername(db, username) {
  return db.prepare(`
    SELECT id, username, password, nombre, rol, activo
    FROM usuarios
    WHERE username = ?
  `).get(username);
}

function verifyPassword(plain, hash) {
  return bcrypt.compareSync(plain, hash);
}

module.exports = { initDatabase, findUserByUsername, verifyPassword };

require('dotenv').config();

const express = require('express');
const path = require('path');
const { initDatabase, findUserByUsername, verifyPassword } = require('./db');

const app = express();
const PORT = process.env.PORT || 3000;

const db = initDatabase();

app.use(express.json());
app.use(express.static(path.join(__dirname, '..', 'public')));

app.post('/api/auth/login', (req, res) => {
  const { username, password } = req.body;

  if (!username || !password) {
    return res.status(400).json({
      success: false,
      message: 'Usuario y contraseña son obligatorios.',
    });
  }

  const user = findUserByUsername(db, username.trim());

  if (!user) {
    return res.status(401).json({
      success: false,
      message: 'Usuario o contraseña incorrectos.',
    });
  }

  if (!user.activo) {
    return res.status(403).json({
      success: false,
      message: 'Su cuenta está desactivada. Contacte con el administrador.',
    });
  }

  const valid = verifyPassword(password, user.password);

  if (!valid) {
    return res.status(401).json({
      success: false,
      message: 'Usuario o contraseña incorrectos.',
    });
  }

  return res.json({
    success: true,
    message: 'Acceso concedido.',
    user: {
      id: user.id,
      username: user.username,
      nombre: user.nombre,
      rol: user.rol,
    },
  });
});

app.get('/api/health', (_req, res) => {
  res.json({ status: 'ok', service: 'Rehab ZSC' });
});

app.listen(PORT, () => {
  console.log(`Rehab ZSC → http://localhost:${PORT}`);
});

